pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation with delay 100
        bytes32 id = c.hashOperation(address(0x1), 0, hex"1234", bytes32(0), bytes32(0));
        c.schedule(address(0x1), 0, hex"1234", bytes32(0), bytes32(0), 100);
        // Warp to exactly the timestamp stored (which is block.timestamp + 100)
        uint256 timestamp = c.getTimestamp(id);
        vm.warp(timestamp);
        // After warp, timestamp equals block.timestamp => _DONE_TIMESTAMP (1) < timestamp but timestamp == block.timestamp
        // Reference: requires timestamp > _DONE_TIMESTAMP && timestamp <= block.timestamp => true since timestamp > 1 and timestamp == block.timestamp
        // Buggy: uses >= _DONE_TIMESTAMP so timestamp == _DONE_TIMESTAMP (1) also returns true, but here timestamp is > 1 so both return true. Need a case where timestamp == _DONE_TIMESTAMP.
        // Actually we need timestamp == _DONE_TIMESTAMP to show divergence. Let's just check that when timestamp == _DONE_TIMESTAMP, reference returns false, buggy returns true.
        // We'll set timestamp to _DONE_TIMESTAMP directly via storage manipulation is not allowed. So instead we schedule an operation with delay such that block.timestamp + delay == _DONE_TIMESTAMP.
        // _DONE_TIMESTAMP = 1, so we need block.timestamp == 0 and delay == 1, but block.timestamp starts at 1 in Foundry (default). So we can warp to block.timestamp = 0 then schedule with delay 1.
        // But we already used setUp with block.timestamp default. Let's do a fresh scenario: deploy new C with a different test.
        // Redeploy in test: not allowed per rules? The setup is fixed, but we can still interact in test.
        // We can schedule with delay 0 and then warp so that timestamp becomes exactly 1.
        // Actually we already used schedule with delay 100. Let's just test the simple case: after scheduling with delay 100, the timestamp is > 1. Both return true. Not good.
        // Instead, schedule with delay 0 (but minDelay is 0) so timestamp = block.timestamp. Then warp to block.timestamp = 1. Then timestamp = 1 which equals _DONE_TIMESTAMP.
        // Let's do that.
        // But we already did a schedule above. We need a clean state. We'll just ignore that and create a new operation.
        // Actually we can cancel the first one. But easier: just use a different salt.
        bytes32 id2 = c.hashOperation(address(0x2), 0, hex"5678", bytes32(0), bytes32(0xdead));
        // Set block.timestamp to 0 via warp
        vm.warp(0);
        c.schedule(address(0x2), 0, hex"5678", bytes32(0), bytes32(0xdead), 1); // delay 1 => timestamp = 0 + 1 = 1 = _DONE_TIMESTAMP
        // Now warp to block.timestamp = 1
        vm.warp(1);
        // Now isOperationReady(id2) = ?
        // Reference: timestamp > _DONE_TIMESTAMP? 1 > 1? false => returns false.
        // Buggy: timestamp >= _DONE_TIMESTAMP? 1 >= 1? true && timestamp <= block.timestamp (1 <= 1) true => returns true.
        // So reference returns false, buggy returns true.
        // Assert that reference returns false (the correct behavior). Since reference is the correct one, we assert isOperationReady(id2) == false.
        assertEq(c.isOperationReady(id2), false);
    }
}

